use serde_json::Value;
use std::process::Command;

pub fn help(command: &str) -> String {
    let temp = tempfile::tempdir().unwrap();
    let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .current_dir(temp.path())
        .env("DATABASE_URL", "invalid-url")
        .args(["data", command, "--help"])
        .output()
        .unwrap();
    assert!(output.status.success());
    assert!(output.stderr.is_empty());
    assert_eq!(std::fs::read_dir(temp.path()).unwrap().count(), 0);
    String::from_utf8(output.stdout).unwrap()
}

pub fn schema(command: &str, label: &str) -> Value {
    let text = help(command);
    let tail = text
        .split_once(label)
        .expect("schema section exists")
        .1
        .trim_start();
    serde_json::Deserializer::from_str(tail)
        .into_iter::<Value>()
        .next()
        .unwrap()
        .unwrap()
}

pub fn validator(command: &str, label: &str) -> jsonschema::Validator {
    jsonschema::options()
        .should_validate_formats(true)
        .build(&schema(command, label))
        .unwrap()
}

pub fn validate(command: &str, label: &str, payload: &Value) {
    validator(command, label).validate(payload).unwrap();
}
use std::process::Command;

use clap::Parser;
use exposed::inbound::cli::DataArgs;
use tempfile::TempDir;

const COMMANDS: &[&[&str]] = &[
    &["latest"],
    &["copy-latest-raw"],
    &["declarations", "fetch"],
    &["declarations", "clean"],
    &["declarations", "resolve"],
    &["declarations", "load"],
    &["members", "fetch"],
    &["members", "load"],
];

#[test]
fn commands_accept_named_config() {
    for command in COMMANDS {
        let args = ["exposed-data"]
            .into_iter()
            .chain(command.iter().copied())
            .chain(["--config", "config.yaml"]);
        assert!(DataArgs::try_parse_from(args).is_ok(), "{command:?}");
    }
}

#[test]
fn commands_require_named_config() -> anyhow::Result<()> {
    let temporary = TempDir::new()?;
    for command in COMMANDS {
        for positional_config in [false, true] {
            let mut process = Command::new(env!("CARGO_BIN_EXE_exposed"));
            process
                .current_dir(temporary.path())
                .arg("data")
                .args(*command);
            if positional_config {
                process.arg("config.yaml");
            }
            let output = process.output()?;
            assert_eq!(output.status.code(), Some(2), "{command:?}");
            assert!(output.stdout.is_empty(), "{command:?}");
            let stderr = String::from_utf8_lossy(&output.stderr);
            if positional_config {
                assert!(
                    stderr.contains("unexpected argument 'config.yaml'"),
                    "{stderr}"
                );
            } else {
                assert!(stderr.contains("--config <CONFIG>"), "{stderr}");
                assert!(stderr.contains("required arguments"), "{stderr}");
            }
        }
    }
    assert_eq!(std::fs::read_dir(temporary.path())?.count(), 0);
    Ok(())
}
#[path = "common/response_schema.rs"]
mod response_schema;

use clap::CommandFactory;
use exposed::inbound::cli::DataArgs;
use serde_json::json;
use std::process::Command;

#[test]
fn every_command_documents_responses_without_configuration_or_side_effects() {
    let command_tree = DataArgs::command();
    for command in command_tree
        .get_subcommands()
        .filter(|command| command.get_name() != "help")
    {
        let command = command.get_name();
        let help = response_schema::help(command);
        assert!(help.contains("https://json-schema.org/draft/2020-12/schema"));
        assert!(help.contains("Failure JSON schema:"));
        assert!(help.contains("Clap argument errors"));
        let output = Command::new(env!("CARGO_BIN_EXE_exposed"))
            .args(["data", command, "-h"])
            .output()
            .unwrap();
        assert!(output.status.success());
        assert!(!String::from_utf8_lossy(&output.stdout).contains("JSON schema:"));
    }
    let help = Command::new(env!("CARGO_BIN_EXE_exposed"))
        .args(["data", "help", "declarations"])
        .env("DATABASE_URL", "invalid-url")
        .output()
        .unwrap();
    assert!(help.status.success());
    assert!(String::from_utf8_lossy(&help.stdout).contains("Success JSON schema (load):"));
    for stage in ["fetch", "clean", "resolve", "load"] {
        response_schema::validator("declarations", &format!("Success JSON schema ({stage}):"));
    }
}

#[test]
fn required_nullable_fields_and_typed_values_reject_malformed_responses() {
    let latest = response_schema::validator("latest", "Success JSON schema:");
    assert!(latest.is_valid(&json!({"ingestion": null})));
    assert!(!latest.is_valid(&json!({})));
    assert!(!latest.is_valid(&json!({"ingestion": {"ingestion_key": "bad", "path": "/data"}})));
    let clean = response_schema::validator("declarations", "Success JSON schema (clean):");
    let mut payload = json!({"ingestion_key":"00000000-0000-4000-8000-000000000001", "path":"/data", "member_partitions":1,"declarations":2,"funders":3,"funding_entries":4});
    assert!(clean.is_valid(&payload));
    payload["declarations"] = json!("2");
    assert!(!clean.is_valid(&payload));
    let load = response_schema::validator("declarations", "Success JSON schema (load):");
    let mut payload = json!({"ingestion_key":"00000000-0000-4000-8000-000000000001", "outcome":"imported", "declarations":2,"funders":3,"funding_entries":4});
    assert!(load.is_valid(&payload));
    payload["outcome"] = json!("unknown");
    assert!(!load.is_valid(&payload));
    let fetch = response_schema::validator("declarations", "Success JSON schema (fetch):");
    let mut payload = json!({"ingestion_key":"00000000-0000-4000-8000-000000000001", "path":"/data", "stage":"fetch"});
    assert!(fetch.is_valid(&payload));
    payload["stage"] = json!("clean");
    assert!(!fetch.is_valid(&payload));
    let member = response_schema::validator("members", "Success JSON schema:");
    payload["stage"] = json!("load");
    assert!(member.is_valid(&payload));
    payload["stage"] = json!("resolve");
    assert!(!member.is_valid(&payload));
    let error = response_schema::validator("latest", "Failure JSON schema:");
    assert!(!error.is_valid(&json!({"error":{}})));
    assert!(!error.is_valid(&json!({"error":{"message":1}})));
}
