use clap::Parser;
use exposed::inbound::{
    cli::{Commands, ExposedCli, IntoResponse, Response, run_cli, run_migrate, run_util},
    http::server::run_server,
};

fn main() -> anyhow::Result<std::process::ExitCode> {
    let args = ExposedCli::parse();
    match args.command {
        Commands::Server => run_server().map(|()| std::process::ExitCode::SUCCESS),
        Commands::Migrate(args) => {
            dotenvy::dotenv().ok();
            let response = match tokio::runtime::Runtime::new() {
                Ok(runtime) => runtime.block_on(run_migrate(args)),
                Err(error) => Err::<Response, _>(error).into_response(),
            };
            Ok(response.write_to(std::io::stdout().lock(), std::io::stderr().lock())?)
        }
        Commands::Data(args) => {
            dotenvy::dotenv().ok();
            let response = match tokio::runtime::Runtime::new() {
                Ok(runtime) => runtime.block_on(run_cli(args)),
                Err(error) => Err::<Response, _>(error).into_response(),
            };
            Ok(response.write_to(std::io::stdout().lock(), std::io::stderr().lock())?)
        }
        Commands::Util(args) => {
            dotenvy::dotenv().ok();
            let response = match tokio::runtime::Runtime::new() {
                Ok(runtime) => runtime.block_on(run_util(args)),
                Err(error) => Err::<Response, _>(error).into_response(),
            };
            Ok(response.write_to(std::io::stdout().lock(), std::io::stderr().lock())?)
        }
    }
}
    Server,
    /// Options to run the `exposed` data pipeline
    Data(DataArgs),
    /// Utilities for inspecting and preparing ingestion runs.
    Util(UtilArgs),
    /// Apply database migrations explicitly.
    Migrate(MigrateArgs),
}

/// CLI Data Args
#[derive(Parser)]
pub struct DataArgs {
    #[command(subcommand)]
    command: DataCommands,
}

/// CLI utility arguments.
#[derive(Parser)]
pub struct UtilArgs {
    #[command(subcommand)]
    command: UtilCommands,
}

#[derive(Subcommand)]
enum UtilCommands {
    /// Show the latest ingestion key and directory path.
    #[command(after_long_help = response_help::single(latest))]
    Latest {
        /// YAML configuration with the ingestion `data_dir`.
        #[arg(long)]
        config: PathBuf,
    },
    /// Copy the latest raw capture into a new ingestion run.
    #[command(after_long_help = response_help::single(copy_latest_raw))]
    CopyLatestRaw {
        /// YAML configuration with the ingestion `data_dir`.
        #[arg(long)]
        config: PathBuf,
        /// Destination ingestion key. Defaults to a fresh UUID-v7.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
}

/// CLI Subcommands
#[derive(Subcommand)]
#[allow(missing_docs)]
pub enum DataCommands {
    #[command(after_long_help = response_help::declarations())]
    Declarations {
        /// Stage to run: fetch, clean, resolve, or load.
        #[arg(value_parser = ["fetch", "clean", "resolve", "load"])]
        stage: String,
        /// YAML configuration containing the declaration `data_dir`.
        #[arg(long)]
        config: PathBuf,
        /// Ingestion run to clean, resolve, or load.
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
    #[command(after_long_help = response_help::single(members))]
    Members {
        stage: String,
        #[arg(long)]
        config: PathBuf,
        #[arg(long)]
        ingestion_key: Option<IngestionKey>,
    },
}

/// Entry point for CLI commands
///
/// Command failures remain in the response until [`Response::write_to`] is called.
///
/// Failures include:
/// - Bad stage arg
/// - Bad config path
/// - Bad config shape
/// - Missing or non-Unicode `DATABASE_URL` for commands that use the database
/// - Service level failures
pub async fn run_cli(args: DataArgs) -> Response {
    match args.command {
        DataCommands::Declarations {
            stage,
            config,
            ingestion_key,
        } => declarations(stage, config, ingestion_key).await,
        DataCommands::Members {
            stage,
            config,
            ingestion_key,
        } => members(stage, config, ingestion_key).await.into_response(),
    }
}

/// Entry point for ingestion utility commands.
pub async fn run_util(args: UtilArgs) -> Response {
    match args.command {
        UtilCommands::Latest { config } => latest(config).await.into_response(),
        UtilCommands::CopyLatestRaw {
            config,
            ingestion_key,
        } => copy_latest_raw(config, ingestion_key).await.into_response(),
    }
}

#[derive(Serialize, JsonSchema)]
struct IngestionResponse<T> {
    /// Ingestion result, or null when the store has no source runs.
    ingestion: Option<T>,
}

#[derive(Serialize, JsonSchema)]
struct IngestionLocation {
    ingestion_key: IngestionKey,
    /// Absolute ingestion run directory.
    path: PathBuf,
}

#[derive(Serialize, JsonSchema)]
struct CopiedIngestion {
    /// Run whose raw capture was copied.
    source_ingestion_key: IngestionKey,
    ingestion_key: IngestionKey,
    /// Absolute destination ingestion run directory.
    path: PathBuf,
}

#[derive(Serialize, JsonSchema)]
struct StageAcknowledgement<S> {
    ingestion_key: IngestionKey,

